from pathlib import Path
import csv,hashlib,json
r1=Path('output-medical-v2-test/run1'); r2=Path('output-medical-v2-test/run2')
ignore={'运行耗时.json','运行耗时.csv'}
for image in sorted(p.name for p in r1.iterdir() if p.is_dir() and not p.name.startswith('.')):
 a=r1/image; b=r2/image
 rels=sorted(p.relative_to(a) for p in a.rglob('*') if p.is_file() and p.name not in ignore)
 rels2=sorted(p.relative_to(b) for p in b.rglob('*') if p.is_file() and p.name not in ignore)
 assert rels==rels2, (image, set(rels)^set(rels2))
 mism=[]
 for rel in rels:
  ha=hashlib.sha256((a/rel).read_bytes()).hexdigest(); hb=hashlib.sha256((b/rel).read_bytes()).hexdigest()
  if ha!=hb: mism.append(str(rel))
 print(image,'files=',len(rels),'hash_mismatches=',len(mism),mism[:8])
 # V2 JSON and CSV consistency: every flattened JSON metric exists in corresponding CSV first row.
 for jp in [p for p in a.rglob('*医学量化指标_V2.json') if p.name!='九项医学量化指标_V2.json']:
  doc=json.loads(jp.read_text()); cp=jp.with_suffix('.csv')
  with cp.open(encoding='utf-8-sig',newline='') as f: rows=list(csv.DictReader(f))
  assert rows
  expected={'检测范围':'全面部','评估状态':'可评估'}
  area=doc['总体指标']['辅助指标']['分析范围']['有效皮肤面积（像素）']
  expected['有效皮肤面积（像素）']=str(area)
  for layer,prefix in [('核心指标','核心'),('辅助指标','辅助')]:
   for group in doc['总体指标'][layer].values():
    for name,value in group.items(): expected[f'{prefix}-{name}']=str(value)
  for key,value in expected.items():
   assert rows[0].get(key)==value,(jp,key,rows[0].get(key),value)
 print('  CSV/JSON overall metrics reconstructable: 9/9')
