def write_medical_metrics(
    json_path: str | Path,
    csv_path: str | Path,
    payload: dict[str, Any],
    project: str,
) -> None:
    """保存 CSV/JSON 完全同口径的医生摘要。

    逐目标坐标和算法质量控制只在内存中参与复算，不进入正式前端 JSON，
    避免单图产生数千行实例明细。JSON 只保留与 CSV 一一对应的总体行和
    分区行。
    """
    safe = json_safe(payload)
    columns = _csv_columns(project)
    rows = [safe["总体指标"], *safe["分区指标"]]
    compact_rows = [
        {key: row.get(key, "") for key in columns}
        for row in rows
    ]
    compact = {
        "检测项目": safe["检测项目"],
        "指标版本": safe["指标版本"],
        "总体指标": compact_rows[0],
        "分区指标": compact_rows[1:],
    }
    Path(json_path).write_text(
        json.dumps(
            compact,
            ensure_ascii=False,
            allow_nan=False,
            indent=2,
        ) + "\n",
        encoding="utf-8",
    )
    with Path(csv_path).open("w", encoding="utf-8-sig", newline="") as handle:
        writer = csv.DictWriter(handle, fieldnames=columns, extrasaction="ignore")
        writer.writeheader()
        writer.writerows(compact_rows)


def _metric_dimension(project: str, name: str) -> str:
    if any(token in name for token in ("面积", "覆盖", "负担", "连续")):
        return "范围与负担"
    if any(token in name for token in ("强度", "红度", "色差", "对比度", "响应")):
        return "信号强度"
    if any(token in name for token in ("密度", "数量", "实例")):
        return "数量与密度"
    if any(token in name for token in ("圆度", "长宽", "点状", "片状", "融合", "形态")):
        return "形态"
    if any(token in name for token in ("左右", "集中", "区域", "聚集")):
        return "分布"
    return "辅助统计"


def _group_v2_metrics(project: str, row: dict[str, Any]) -> tuple[dict[str, Any], dict[str, Any]]:
    base = {"检测范围", "评估状态", "有效皮肤面积（像素）"}
    core_names = set(V2_CORE_METRICS[project])
    core: dict[str, dict[str, Any]] = {}
    auxiliary: dict[str, dict[str, Any]] = {
        "分析范围": {
            "检测范围": row.get("检测范围", UNAVAILABLE),
            "评估状态": row.get("评估状态", UNAVAILABLE),
            "有效皮肤面积（像素）": row.get("有效皮肤面积（像素）", UNAVAILABLE),
        }
    }
    for name, value in row.items():
        if name in base or name.startswith("画面左右"):
            continue
        target = core if name in core_names else auxiliary
        target.setdefault(_metric_dimension(project, name), {})[name] = value
    return core, auxiliary


def build_medical_metrics_v2(payload: dict[str, Any], project: str) -> dict[str, Any]:
    """把现有可复算医学摘要转换为 V2；不携带逐实例和内部调试数组。"""
    safe = json_safe(payload)
    overall = dict(safe["总体指标"])
    core, auxiliary = _group_v2_metrics(project, overall)
    region_rows: list[dict[str, Any]] = []
    for row in safe["分区指标"]:
        region_core, region_auxiliary = _group_v2_metrics(project, row)
        region_rows.append({
            "检测范围": row.get("检测范围", UNAVAILABLE),
            "评估状态": row.get("评估状态", UNAVAILABLE),
            "有效皮肤面积（像素）": row.get("有效皮肤面积（像素）", UNAVAILABLE),
            "核心指标": region_core,
            "辅助指标": region_auxiliary,
        })
    left_right = {
        name: value for name, value in overall.items() if name.startswith("画面左右")
    }
    return json_safe({
        "检测项目": safe["检测项目"],
        "指标版本": MEDICAL_V2_VERSION,
        "评分状态": "uncalibrated",
        "成像与单位说明": safe.get("成像与单位说明", {}),
        "总体指标": {"核心指标": core, "辅助指标": auxiliary},
        "分区指标": region_rows,
        "左右比较": left_right,
        "质量控制": safe.get("质量控制", {}),
        "医学局限性": safe.get("医学局限性", []),
    })


def _flatten_metric_groups(groups: dict[str, Any], prefix: str) -> dict[str, Any]:
    output: dict[str, Any] = {}
    base_names = {"检测范围", "评估状态", "有效皮肤面积（像素）"}
    for metrics in groups.values():
        if not isinstance(metrics, dict):
            continue
        for name, value in metrics.items():
            if name not in base_names:
                output[f"{prefix}-{name}"] = value
    return output


def write_medical_metrics_v2(
    json_path: str | Path,
    csv_path: str | Path,
    payload: dict[str, Any],
    project: str,
) -> dict[str, Any]:
    """保存医生 V2 宽表和可逐项还原该宽表的紧凑 JSON。"""
    document = build_medical_metrics_v2(payload, project)
    source_rows = [{
        "检测范围": document["总体指标"]["辅助指标"]["分析范围"]["检测范围"],
        "评估状态": document["总体指标"]["辅助指标"]["分析范围"]["评估状态"],
        "有效皮肤面积（像素）": document["总体指标"]["辅助指标"]["分析范围"]["有效皮肤面积（像素）"],
        **document["总体指标"],
    }, *document["分区指标"]]
    flat_rows: list[dict[str, Any]] = []
    for row in source_rows:
        flat_rows.append({
            "检测范围": row["检测范围"],
            "评估状态": row["评估状态"],
            "有效皮肤面积（像素）": row["有效皮肤面积（像素）"],
            **_flatten_metric_groups(row.get("核心指标", {}), "核心"),
            **_flatten_metric_groups(row.get("辅助指标", {}), "辅助"),
        })
    columns = list(flat_rows[0])
    for row in flat_rows[1:]:
        for name in row:
            if name not in columns:
                columns.append(name)
        raise ValueError("algorithms 必须是算法名称列表")

    normalized = [str(name).strip() for name in algorithms]
    if not normalized or any(not name for name in normalized):
        raise ValueError("algorithms 不能为空")
    if len(set(normalized)) != len(normalized):
        raise ValueError("algorithms 不能包含重复项目")

    unknown = sorted(set(normalized) - set(_SUPPORTED_ALGORITHMS))
    if unknown:
        raise ValueError(f"不支持的算法: {unknown}")
    return normalized


def _load_and_validate_metrics(
    metrics_path: str,
    report_path: str,
) -> dict[str, int]:
    """恢复原前端合同：棕区/纹理/毛孔使用精简中文整数 dict。"""
    with open(metrics_path, "r", encoding="utf-8") as handle:
        metrics = json.load(handle)
    if not isinstance(metrics, dict) or not metrics:
        raise ValueError("量化 JSON 必须是非空对象")

    normalized_metrics: dict[str, int] = {}
    for raw_name, raw_value in metrics.items():
        name = str(raw_name)
        if not any("\u4e00" <= character <= "\u9fff" for character in name):
            raise ValueError(f"量化指标名称必须使用中文: {name}")
        if isinstance(raw_value, bool) or not isinstance(raw_value, int):
            raise ValueError(f"量化指标值必须是整数: {name}={raw_value!r}")
        normalized_metrics[name] = raw_value

    with open(report_path, "r", encoding="utf-8-sig", newline="") as handle:
        rows = list(csv.reader(handle))
    if len(rows) != 2 or len(rows[0]) != len(rows[1]):
        raise ValueError("量化 CSV 必须严格为等长的表头行和数据行")
    try:
        csv_metrics = {
            name: int(value) for name, value in zip(rows[0], rows[1])
        }
    except ValueError as exc:
        raise ValueError("量化 CSV 的数据必须是整数") from exc
    if csv_metrics != normalized_metrics:
        raise ValueError("量化 JSON 与 CSV 的中文指标和值不一致")
    return normalized_metrics


def _build_medical_v2_additions(
    pipeline_result: dict,
    algorithm: str,
    result_prefix: str,
    record_component: str,
) -> dict:
    """校验并上传医学 V2 旁路；任何异常均不影响旧任务成功。"""
    if not settings.enable_medical_metrics_v2:
        return {}
    try:
        spec = (pipeline_result.get("medical_v2_results") or {}).get(algorithm)
        if not isinstance(spec, dict):
            raise ValueError(f"缺少 {algorithm} 医学 V2 产物")
        if algorithm == "purple":
            artifacts = spec.get("artifacts") or []
            pairs = [
                (item.get("json"), item.get("csv"))
                for item in artifacts if isinstance(item, dict)
            ]
            if len(pairs) != 2 or any(not json_path or not csv_path for json_path, csv_path in pairs):
                raise ValueError("紫区医学 V2 必须包含 UV 色斑和紫质两个子项目")
            csv_path = Path(str(spec.get("combined_csv") or ""))
            document = combine_documents(pairs, csv_path)
        else:
            json_path = spec.get("json")
            csv_path = Path(str(spec.get("csv") or ""))
            if not json_path or not str(csv_path):
                raise ValueError(f"{algorithm} 医学 V2 路径不完整")
            document = load_and_validate(json_path, csv_path)
        if not csv_path.is_file() or csv_path.stat().st_size <= 0:
            raise ValueError("医学 V2 CSV 不存在或为空")
        oss_path = f"{result_prefix}{record_component}/{csv_path.name}"
        oss_storage.upload_file(str(csv_path), oss_path)
        return {
            "medical_metrics_v2": document,
            "medical_report_csv_v2": oss_path,
        }
    except Exception:
        logger.exception(
            "Record %s: 医学 V2 旁路失败，保留旧合同成功返回",
            record_component,
        )
        return {}


def submit_independent_tasks(
    task_ids: Mapping[str, str],
    oss_key: str,
    oss_result_prefix: str | None = None,
    *,
    app=None,
) -> dict[str, dict[str, str]]:
    """Submit five independent single-algorithm tasks.

    The backend owns the five business record IDs.  This helper deliberately
    does not aggregate results: each Celery task has its own final result.
    """
    if not isinstance(task_ids, Mapping):
        raise ValueError("task_ids 必须是算法到独立 task_id 的映射")

    # 该助手是现有后端的“五项并行”固定合同，新增紫区不能把它从五项
    # 变成六项必填。紫区由后端另行提交 algorithms=["purple"]。
    dispatch_algorithms = tuple(_DEFAULT_ALGORITHMS)
    missing = sorted(set(dispatch_algorithms) - set(task_ids))
    extra = sorted(set(task_ids) - set(dispatch_algorithms))
    if missing or extra:
        raise ValueError(f"task_ids 算法集合不完整: missing={missing}, extra={extra}")
    if not str(oss_key).strip():
        raise ValueError("oss_key 不能为空")

    record_ids = {name: str(task_ids[name]).strip() for name in dispatch_algorithms}
    if any(not value for value in record_ids.values()):
        raise ValueError("五个 task_id 均不能为空")
    if len(set(record_ids.values())) != len(record_ids):
        raise ValueError("五个任务必须使用不同的 task_id")

    safe_components = [_safe_record_component(value) for value in record_ids.values()]
    if len(set(safe_components)) != len(safe_components):
        raise ValueError("task_id 规范化后发生路径冲突，请使用差异更明确的 ID")

    sender = app or celery_app
    submitted: dict[str, dict[str, str]] = {}
    for algorithm in dispatch_algorithms:
        record_id = record_ids[algorithm]
        async_result = sender.send_task(
            "dermavision.analyze_image",
            args=[
                record_id,
                oss_key,
                oss_result_prefix,
                [algorithm],
            ],
            queue=algorithm,
        )
        submitted[algorithm] = {
            "record_id": record_id,
            "celery_task_id": str(async_result.id),
        }
    return submitted


def _cleanup_success_outputs(paths: list[str]) -> None:
    """Delete only files/directories inside this project's output root."""
    unique = sorted({str(path) for path in paths if path}, key=len, reverse=True)
    for raw_path in unique:
        candidate = Path(raw_path).resolve()
        if candidate == OUTPUT_ROOT or OUTPUT_ROOT not in candidate.parents:
            logger.warning("跳过不安全的清理路径: %s", candidate)
            continue
        try:
            if candidate.is_dir():
                shutil.rmtree(candidate)
            elif candidate.is_file():
                candidate.unlink()
        except OSError as exc:
            logger.warning("清理本地结果失败 %s: %s", candidate, exc)


_ENVELOPE_ALGOS = {"redness", "spots", "brown", "texture", "pores", "purple"}


def _build_envelope_response(
    record_id: str,
    algorithms: list[str],
    raw_result: dict,
    metadata: dict,
    medical_v2_additions: dict | None = None,
) -> dict:
    """按 AGENTS.md 构建单算法五字段信封，算法内部结果保持不变。"""
    algo = algorithms[0]
    if algo == "purple":
        algorithm_result = {
            "uv_base": raw_result.get("purple_uv_base"),
            "uv_spots_overlay": raw_result.get("purple_uv_spots_overlay"),
            "fluorescence_base": raw_result.get("purple_fluorescence_base"),
            "porphyrin_overlay": raw_result.get("purple_porphyrin_overlay"),
            "metrics": raw_result.get("purple_metrics"),
            "quality_score": metadata.get("quality_score"),
            "quality_status": metadata.get("quality_status"),
            "quality_flags": metadata.get("quality_flags", []),
        }
    else:
        algorithm_result = {
            "overlay": raw_result.get(algo),
            "metrics": raw_result.get(f"{algo}_metrics"),
            "quality_score": metadata.get("quality_score"),
            "quality_status": metadata.get("quality_status"),
            "quality_flags": metadata.get("quality_flags", []),
            **(
                {"brown_spots_overlay": raw_result.get("brown_spots_overlay")}
                if algo == "brown"
                else {}
            ),
            **(
                {"red_areas_overlay": raw_result.get("red_areas_overlay")}
                if algo == "redness"
                else {}
            ),
        }
    if medical_v2_additions:
        algorithm_result.update(medical_v2_additions)
    return {
        "record_id": record_id,
        "status": "success",
        "meta_data": {
            "name": algo,
            "version": "1",
        },
        "raw_result": algorithm_result,
        "debug_info": {
            "report_csv": raw_result.get(f"{algo}_report"),
            "timing_seconds": metadata.get("timing_seconds", {}),
            "execution_mode": metadata.get("execution_mode", ""),
        },
    }


