"""医学 V2 旁路产物的严格校验与紫区合并工具。

该模块只处理已经生成的报告文件，不参与检测，也不修改旧 metrics。
"""

from __future__ import annotations

import csv
import json
import math
from pathlib import Path
from typing import Any, Iterable

from src.medical_v2_schema import (
    is_english_document,
    to_chinese_document,
    to_english_document,
)


REQUIRED_DOCUMENT_KEYS = {
    "检测项目",
    "指标版本",
    "评分状态",
    "成像与单位说明",
    "总体指标",
    "分区指标",
    "左右比较",
    "质量控制",
    "医学局限性",
}
REQUIRED_PUBLIC_DOCUMENT_KEYS = {
    "project",
    "metrics_version",
    "scoring_status",
    "imaging_and_units",
    "overall_metrics",
    "region_metrics",
    "left_right_comparison",
    "quality_control",
    "medical_limitations",
}


def _reject_json_constant(value: str) -> None:
    raise ValueError(f"医学 V2 JSON 包含非法数值: {value}")


def _assert_finite(value: Any, path: str = "$") -> None:
    if isinstance(value, float) and not math.isfinite(value):
        raise ValueError(f"医学 V2 JSON 包含非有限数值: {path}")
