def validate_document(document: Any) -> dict[str, Any]:
    if not isinstance(document, dict):
        raise ValueError("医学 V2 JSON 顶层必须是对象")
    if is_english_document(document):
        required = (
            REQUIRED_INCREMENTAL_DOCUMENT_KEYS
