@worker_process_shutdown.connect
def _close_worker_process(**_kwargs) -> None:
    global _pipeline
    if _pipeline is not None:
        _pipeline.close()
        _pipeline = None


def _upload_result_group(
    *,
    record_id: str,
    result_prefix: str,
    files: dict[str, str],
    use_basename: bool,
) -> dict[str, str]:
    uploaded: dict[str, str] = {}
    for name, local_path in files.items():
        path = Path(local_path)
        if not path.exists():
            logger.warning("Record %s: result file missing: %s", record_id, local_path)
            continue
        if use_basename:
            object_name = path.name
        else:
            suffix = path.suffix or ".bin"
            object_name = f"{name}{suffix}"
        oss_path = f"{result_prefix}{record_id}/{object_name}"
        try:
            oss_storage.upload_file(str(path), oss_path)
        except StorageError as exc:
            logger.exception("Record %s: result upload failed: %s", record_id, name)
            raise
        uploaded[name] = oss_path
    return uploaded


def _build_medical_v2_additions(
