            record_id,
        )
        return {}


@celery_app.task(name=f"{_SERVICE_NAME}.analyze_image", queue=_SERVICE_NAME, bind=True)
def analyze_image(self, task_id, oss_key, oss_result_prefix=None, algorithms=None):
    """从 OSS 下载单张图片，运行分析流程，并上传结果产物。"""

    record_id = str(task_id)
    result_prefix = oss_result_prefix or settings.oss_result_prefix or f"{_SERVICE_NAME}/v1/"
    logger.info("Record %s: start oss_key=%s algorithms=%s", record_id, oss_key, algorithms)

    try:
        img_bytes = oss_storage.download_bytes(oss_key)
    except StorageError as exc:
        logger.exception("Record %s: image download failed", record_id)
        return {"record_id": record_id, "status": "failed", "error_message": str(exc)}

    with tempfile.TemporaryDirectory(prefix=f"{_SERVICE_NAME}_{record_id}_") as tmpdir:
        input_path = os.path.join(tmpdir, f"{record_id}.jpg")
        with open(input_path, "wb") as f:
            f.write(img_bytes)

        medical_v2_additions = {}
        try:
            pipeline_result = _get_pipeline().process_single(input_path, algorithms)
        except DetectorUnavailableError as exc:
            logger.exception("Record %s: detector deployment validation failed", record_id)
            return {
                "record_id": record_id,
                "status": "failed",
                "error_code": "detector_deployment_error",
                "error_message": str(exc),
            }
        except Exception as exc:
            logger.exception("Record %s: pipeline crashed", record_id)
            return {"record_id": record_id, "status": "failed", "error_message": f"{type(exc).__name__}: {exc}"}

        if pipeline_result.get("status") != "success":
            message = pipeline_result.get("message", "analysis_failed")
            logger.warning("Record %s: pipeline failed - %s", record_id, message)
            return {"record_id": record_id, "status": "failed", "error_message": message}

        raw_dir = Path(pipeline_result.get("output_dir", ""))
        summary_path = Path(pipeline_result.get("summary_path", ""))
        if not raw_dir.exists() or not summary_path.exists():
            logger.error("Record %s: pipeline returned without a valid output directory", record_id)
            return {
                "record_id": record_id,
                "status": "failed",
                "error_code": "missing_output_directory",
                "error_message": "pipeline did not produce a valid output directory",
            }

        try:
            display_files, compact_summary, metadata = build_display_outputs(
                raw_dir=raw_dir,
                input_image=oss_key,
                target_dir=raw_dir,
                raw_result_files=pipeline_result.get("results", {}),
            )
            raw_result = _upload_result_group(
                record_id=record_id,
                result_prefix=result_prefix,
                files=pipeline_result.get("results", {}),
                use_basename=False,
            )
            display_result = _upload_result_group(
                record_id=record_id,
                result_prefix=result_prefix,
                files=display_files,
                use_basename=True,
            )
            medical_v2_additions = _build_medical_v2_additions(
                record_id=record_id,
                result_prefix=result_prefix,
                output_dir=raw_dir,
            )
        except StorageError as exc:
            return {"record_id": record_id, "status": "failed", "error_message": str(exc)}
        except Exception as exc:
            logger.exception("Record %s: failed to build display outputs", record_id)
            return {
                "record_id": record_id,
                "status": "failed",
                "error_code": "display_result_build_failed",
                "error_message": f"{type(exc).__name__}: {exc}",
            }

    # algorithm_version 已写死 "1"，不再从环境变量读取
    quant_result = compact_summary["量化结果"]
    logger.info("Record %s: success raw_result=%s display_result=%s", record_id, raw_result, display_result)
    return {
        "record_id": record_id,
        "status": "success",
        "meta_data": {"name": "acne", "version": "1"},
        "raw_result": {
            # OSS key 字段（最终产物文件）
            "acne_summary": raw_result.get("acne_summary"),
            "acne_circles": raw_result.get("acne_circles"),
            "acne_raw_boxes": raw_result.get("acne_raw_boxes"),
            "acne_detections": raw_result.get("acne_detections"),
            "acne_skin_mask": raw_result.get("acne_skin_mask"),
            "acne_forbidden_mask": raw_result.get("acne_forbidden_mask"),
            "acne_standardized": raw_result.get("acne_standardized"),
            "max_recall_heatmap": raw_result.get("max_recall_heatmap"),
            "diffuse_erythema_heatmap": raw_result.get("diffuse_erythema_heatmap"),
            "focal_candidate_heatmap": raw_result.get("focal_candidate_heatmap"),
            "max_recall_circles": raw_result.get("max_recall_circles"),
    display_results: dict[str, str],
    raw_result: dict[str, str],
) -> dict:
    """从完整 raw_result 中标记当前需要给用户展示的文件。"""

    def build_fixed(result_key: str | None):
        if not result_key or result_key not in raw_result:
            return None
        local_path = display_results.get(result_key, "")
        return {
            "file_name": Path(local_path).name or Path(raw_result[result_key]).name,
            "oss_key": raw_result[result_key],
        }

    regions = []
    for item in display_manifest.get("regions", []):
        result_key = item.get("result_key")
        if not result_key or result_key not in raw_result:
            continue
        region = {key: value for key, value in item.items() if key != "result_key"}
        region["image_oss_key"] = raw_result[result_key]
        regions.append(region)

    return {
        "overview": build_fixed(display_manifest.get("overview_result_key")),
        "texture": build_fixed(display_manifest.get("texture_result_key")),
        "regions": regions,
    }


def _cleanup_success_output(output_dir: str | None, local_results: dict[str, str]) -> None:
    """成功上传后清理本次运行目录；失败任务不调用本函数。"""
    configured_root = Path(settings.wrinkle_output_dir)
    if not configured_root.is_absolute():
        configured_root = PROJECT_ROOT / configured_root
    configured_root = configured_root.resolve()

    if output_dir:
        candidate = Path(output_dir).resolve()
        if candidate != configured_root and configured_root in candidate.parents:
            shutil.rmtree(candidate, ignore_errors=False)
            return
        logger.warning("跳过不安全的运行目录清理路径: %s", candidate)
        return

    for local_path in local_results.values():
        try:
            local_file = Path(local_path).resolve()
            if configured_root in local_file.parents and local_file.is_file():
                local_file.unlink()
            elif local_file.is_file():
                logger.warning("跳过 output 根目录之外的文件清理: %s", local_file)
        except OSError as e:
            logger.warning("清理本地文件失败 %s: %s", local_path, e)


def _build_result_oss_path(
    result_prefix: str,
    record_id: str,
    name: str,
    local_path: str,
    upload_relative_paths: dict[str, str],
) -> str:
    relative_path = upload_relative_paths.get(name)
    if relative_path:
        safe_relative = Path(relative_path)
        if safe_relative.is_absolute() or ".." in safe_relative.parts:
            raise ValueError(f"Invalid upload relative path: {relative_path!r}")
        return f"{result_prefix}{record_id}/{safe_relative.as_posix()}"
    suffix = Path(local_path).suffix or ".jpg"
    return f"{result_prefix}{record_id}/{name}{suffix}"


