def _wrinkle(raw: dict[str, Any]) -> tuple[dict[str, Any], dict[str, dict[str, float]]]:
    regions = raw.get("region_metrics") or []
    segment_count = sum(float(x.get("segment_count") or 0) for x in regions)
    wrinkle_pixels = sum(float(x.get("wrinkle_pixels") or 0) for x in regions)
    area = sum(float(x.get("area_px") or 0) for x in regions)
    weighted = sum(float(x.get("relative_score") or 0) * float(x.get("wrinkle_pixels") or 0) for x in regions)
    weighted = weighted / wrinkle_pixels if wrinkle_pixels else 0.0
    max_length = max((float(x.get("max_segment_length") or 0) for x in regions), default=0.0)
    named_count = sum(float(x.get("segment_count") or 0) for x in regions if x.get("region_key") != "other")
    density = wrinkle_pixels / area if area else 0.0
    summary = {
        "纹路线段数量（段）": int(segment_count), "命名分区纹路线段数量（段）": int(named_count),
        "皱纹中心线像素（像素）": int(wrinkle_pixels), "分区面积（像素）": int(area),
        "皱纹像素面积占比": density, "最大线段长度（像素）": max_length,
        "按皱纹像素加权相对响应（0～100）": weighted,
        "建议皱纹区域占比": raw.get("stage2_recommended_ratio"),
        "主要分区": regions[0].get("region_name") if regions else "不可评估",
    }
    features = {
        "常见部位匹配": {"命名分区线段数量": named_count},
        "线性形态": {"最大线段长度": max_length, "中心线面积占比": density},
        "宽度和视觉强度": {"加权相对响应": weighted},
    }
    return summary, features


def _acne(raw: dict[str, Any]) -> tuple[dict[str, Any], dict[str, dict[str, float]]]:
    detection = raw.get("detection") or {}
    detections = detection.get("detections") or []
    skin = _number((raw.get("preprocess") or {}).get("skin_pixels")) or 0.0
    count = float(detection.get("count") or 0)
    density = count * 100000.0 / skin if skin else 0.0
    confidences = sorted(float(x.get("confidence") or 0) for x in detections)
    mean_conf = sum(confidences) / len(confidences) if confidences else 0.0
    p90_conf = confidences[min(len(confidences) - 1, int(0.9 * len(confidences)))] if confidences else 0.0
    grading = raw.get("grading") or {}
    summary = {
        "候选数量（个）": int(count), "单位面积密度（个/10万皮肤像素）": density,
        "平均置信度（0～1）": mean_conf, "P90置信度（0～1）": p90_conf,
        "检测范围": detection.get("detection_scope"), "Acne-LDS状态": grading.get("status"),
        "Acne-LDS等级": grading.get("severity_level"), "Acne-LDS等级概率": grading.get("severity_probabilities") or [],
    }
    features = {
        "模型候选数量密度及面积": {"候选密度": density},
        "候选置信度及聚集": {"平均置信度": mean_conf, "P90置信度": p90_conf},
    }
    severity = _number(grading.get("severity_level"))
    if severity is not None:
        features["Acne-LDS等级概率"] = {"预测等级": severity}
    return summary, features


def extract_item(item: str, raw: dict[str, Any] | None) -> tuple[dict[str, Any], dict[str, dict[str, float]]]:
    if not isinstance(raw, dict):
        return {}, {}
    if raw.get("指标版本") in {"acne_review_metrics_v1", "wrinkle_review_metrics_v1"}:
        return raw.get("总体指标") or {}, {}
    if item in {"redness", "spots", "brown", "texture", "pores"}:
        overall = raw.get("总体指标") or {}
        return _pick(overall, *COMMON_KEYS), _derma_features(item, overall)
    if item in {"uv_spots", "porphyrin"}:
        return _purple(item, raw.get("总体指标") or {})
    if item == "wrinkle":
        return _wrinkle(raw)
    if item == "acne":
        return _acne(raw)
    raise KeyError(item)
from __future__ import annotations

import csv
import json
import math
import sqlite3
from datetime import datetime
from pathlib import Path
from typing import Any, Iterable


QUANTILES = {
    "q005": 0.005, "q10": 0.10, "q25": 0.25, "q50": 0.50,
    "q75": 0.75, "q90": 0.90, "q95": 0.95, "q995": 0.995,
}


def transform_name(metric: str) -> str:
    if "占比" in metric or "比例" in metric or "强度" in metric or "置信度" in metric or "响应" in metric:
        return "identity"
    if any(token in metric for token in ("数量", "密度", "面积", "长度", "像素", "聚集")):
        return "log1p"
    return "identity"


def transform_value(value: float, transform: str) -> float:
    return math.log1p(max(0.0, value)) if transform == "log1p" else value


def iter_feature_rows(paths: Iterable[Path]) -> Iterable[tuple[str, str, str, float, str]]:
    for path in paths:
        data = json.loads(path.read_text(encoding="utf-8"))
        for item, groups in (data.get("九项评分输入") or {}).items():
            for group, metrics in (groups or {}).items():
                for metric, raw in (metrics or {}).items():
                    if isinstance(raw, bool) or not isinstance(raw, (int, float)) or not math.isfinite(float(raw)):
                        continue
                    transform = transform_name(metric)
                    yield item, group, metric, transform_value(float(raw), transform), transform


def _quantile(sorted_values: list[float], q: float) -> float:
    if not sorted_values:
        raise ValueError("empty values")
    pos = (len(sorted_values) - 1) * q
    lo, hi = int(math.floor(pos)), int(math.ceil(pos))
    if lo == hi:
        return sorted_values[lo]
    return sorted_values[lo] + (sorted_values[hi] - sorted_values[lo]) * (pos - lo)


def build_profile(feature_paths: list[Path], output: Path, minimum_samples: int = 1000) -> dict[str, Any]:
    output.parent.mkdir(parents=True, exist_ok=True)
    database = output.with_suffix(".sqlite3")
    if database.exists():
        database.unlink()
    connection = sqlite3.connect(database)
    try:
        connection.execute("CREATE TABLE values_table (item TEXT, group_name TEXT, metric TEXT, value REAL, transform TEXT)")
        batch = []
        for row in iter_feature_rows(feature_paths):
            batch.append(row)
            if len(batch) >= 10000:
                connection.executemany("INSERT INTO values_table VALUES (?, ?, ?, ?, ?)", batch)
                batch.clear()
        if batch:
            connection.executemany("INSERT INTO values_table VALUES (?, ?, ?, ?, ?)", batch)
        connection.commit()
        keys = connection.execute(
            "SELECT item, group_name, metric, transform, COUNT(*) FROM values_table GROUP BY item, group_name, metric, transform"
        ).fetchall()
        metrics: dict[str, Any] = {}
        minimum_count = min((int(row[4]) for row in keys), default=0)
        for item, group, metric, transform, count in keys:
            values = [float(row[0]) for row in connection.execute(
                "SELECT value FROM values_table WHERE item=? AND group_name=? AND metric=? ORDER BY value",
                (item, group, metric),
            )]
            entry = {"count": int(count), "transform": transform, "min": values[0], "max": values[-1]}
            entry.update({name: _quantile(values, q) for name, q in QUANTILES.items()})
            metrics.setdefault(item, {}).setdefault(group, {})[metric] = entry
        calibrated = bool(keys) and minimum_count >= minimum_samples
        profile = {
            "profile_version": "aisia_reference_distribution_v1",
            "created_at": datetime.now().astimezone().isoformat(),
            "status": "calibrated" if calibrated else "insufficient_samples",
            "reason": "" if calibrated else f"至少一个指标有效样本数低于 {minimum_samples}",
            "input_files": len(feature_paths),
            "minimum_metric_samples": minimum_count,
            "required_minimum_samples": minimum_samples,
            "winsor_limits": [0.005, 0.995],
            "metrics": metrics,
            "medical_boundary": "AISIA内部参考人群相对分布，不代表医学正常值。",
        }
        output.write_text(json.dumps(profile, ensure_ascii=False, indent=2), encoding="utf-8")
        return profile
    finally:
        connection.close()


def read_feature_manifest(path: Path) -> list[Path]:
    rows = csv.DictReader(path.open(encoding="utf-8-sig"))
    result = []
    for row in rows:
        raw = row.get("scoring_features_path") or row.get("评分输入路径")
        if raw and Path(raw).is_file():
            result.append(Path(raw).resolve())
    return result
